function drawMini(){const mw=145,mh=112;mctx.clearRect(0,0,mw,mh);mctx.fillStyle='rgba(8,20,30,.94)';mctx.fillRect(0,0,mw,mh);mctx.strokeStyle='rgba(155,205,225,.12)';mctx.lineWidth=1;for(let i=0;i<8;i++){let x=i*24-(player.x*.075%24);mctx.fillRect(x,18,8,mh-18)}mctx.fillStyle='rgba(43,63,76,.9)';for(let i=-1;i<10;i++){let bx=i*33-(player.x*.1%33);mctx.fillRect(bx,30+(i%3)*9,21,36+(i%4)*8)}mctx.strokeStyle='rgba(98,232,255,.5)';mctx.beginPath();mctx.moveTo(0,mh*.77);mctx.lineTo(mw,mh*.77);mctx.stroke();for(const e of enemies){let ex=mw*.5+(e.x-player.x)*.075;if(ex>0&&ex<mw){mctx.fillStyle='#ff777a';mctx.fillRect(ex,mh*.57,3,3)}}mctx.fillStyle='#65edff';mctx.beginPath();mctx.arc(mw*.5,mh*.57,3,0,7);mctx.fill();mctx.fillStyle='rgba(98,232,255,.3)';mctx.beginPath();mctx.arc(mw*.5,mh*.57,7,0,7);mctx.fill()}
function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawSky();let camera=player.x-w*.36;
 // aerial signal and route beacon
 let signalX=missionDist-camera;let signalY=groundY-150;ctx.save();ctx.translate(signalX,signalY);let pulse=1+Math.sin(performance.now()*.004)*.15;ctx.strokeStyle='rgba(255,195,112,.65)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,15*pulse,0,7);ctx.stroke();ctx.beginPath();ctx.moveTo(0,14);ctx.lineTo(0,180);ctx.stroke();ctx.fillStyle='#ffd38e';ctx.font='8px sans-serif';ctx.textAlign='center';ctx.fillText('PIER 41 SIGNAL',0,-22);ctx.restore();
 const near=getBuildings(camera-100,w+camera+100);near.sort((a,b)=>a.h-b.h);for(const b of near)drawBuilding(b,camera);drawStreet(camera);
 // Web tether to actual roof anchor
 if(player.swing){const sx=player.swing.x-camera,sy=groundY-player.swing.y,px=w*.36,py=groundY-player.y;ctx.save();ctx.strokeStyle='rgba(180,249,255,.95)';ctx.lineWidth=1.5;ctx.shadowColor='#65eaff';ctx.shadowBlur=9;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(px,py);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#e2ffff';ctx.beginPath();ctx.arc(sx,sy,3.2,0,7);ctx.fill();ctx.restore()}
 // anchor target
 let a=nearestAnchor();if(a&&!player.swing){let ax=a.x-camera,ay=groundY-a.y;ctx.strokeStyle='rgba(98,232,255,.78)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(ax,ay,6+Math.sin(performance.now()*.01)*1.5,0,7);ctx.moveTo(ax-10,ay);ctx.lineTo(ax-5,ay);ctx.moveTo(ax+5,ay);ctx.lineTo(ax+10,ay);ctx.moveTo(ax,ay-10);ctx.lineTo(ax,ay-5);ctx.moveTo(ax,ay+5);ctx.lineTo(ax,ay+10);ctx.stroke()}
 for(const e of enemies)drawEnemy(e,camera);for(const p of particles){ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(p.x-camera,groundY-p.y,p.size,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;
 let sx=w*.36,sy=groundY-player.y;if(player.launchFlash>0){ctx.strokeStyle=`rgba(118,241,255,${player.launchFlash*1.5})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(sx,sy,40+(0.5-player.launchFlash)*100,15+(0.5-player.launchFlash)*40,0,0,7);ctx.stroke()}drawPlayer(sx,sy);
 // wind streaks at velocity
 if(player.vx>360){ctx.strokeStyle='rgba(198,239,250,.2)';ctx.lineWidth=1;for(let i=0;i<5;i++){let yy=sy-35+i*17;ctx.beginPath();ctx.moveTo(sx-65-Math.random()*45,yy);ctx.lineTo(sx-28,yy);ctx.stroke()}}
 // soft sunset lens flare and dynamic weather rain toward waterfront
 if(player.x>2800){ctx.fillStyle='rgba(130,177,192,.07)';ctx.fillRect(0,0,w,h);for(const r of rain){r.x-=r.s*.016;r.y+=r.s*.025;if(r.x<0)r.x=w;if(r.y>h)r.y=0;ctx.strokeStyle='rgba(181,222,239,.16)';ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-5,r.y+13);ctx.stroke()}}
 ctx.restore();drawMini();}
function frame(now){if(!started)return;let dt=Math.min(.034,(now-last)/1000||.016);last=now;if(slow>0)dt*=.57;update(dt);draw();requestAnimationFrame(frame)}
// Accessible pointer controls; action buttons stay held for the duration of a touch.
const touchMap={left:'arrowleft',right:'arrowright',up:'arrowup',down:'arrowdown',swing:'e',jump:' ',strike:'j',launch:'f'};
document.querySelectorAll('[data-key]').forEach(btn=>{const key=touchMap[btn.dataset.key];const down=e=>{e.preventDefault();btn.setPointerCapture?.(e.pointerId);if(key==='e'){heldSwing=true;keys.e=true}else if(key===' '){keys.space=true;jump()}else if(key==='j')attack();else if(key==='f')pointLaunch();else keys[key]=true;btn.style.background='rgba(62,176,195,.55)'};const up=e=>{e.preventDefault();if(key==='e'){heldSwing=false;keys.e=false;if(player.swing)releaseSwing()}else keys[key]=false;btn.style.background=''};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});
// Keep the game alive while the player reads the intro; draw the world beneath it.
function idle(){if(started)return;draw();requestAnimationFrame(idle)}requestAnimationFrame(idle);
})();
</script>
</body>
</html>

