(()=>{
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),map=document.querySelector('#minimap'),mctx=map.getContext('2d');const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),randSeed=n=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
let w=innerWidth,h=innerHeight,dpr=1,groundY=0,last=0,started=false,shake=0,slow=0,toastTimer=0,missionDist=3000,missionDone=false,enemyTimer=1;function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);map.width=290*dpr;map.height=224*dpr;mctx.setTransform(dpr,0,0,dpr,0,0);groundY=h*.77}addEventListener('resize',resize);resize();
const keys={};let heldSwing=false,player={x:70,y:20,vx:210,vy:0,health:100,focus:100,style:0,combo:1,ground:false,swing:null,wall:false,invuln:0,attack:0,dodge:0,launchFlash:0};let enemies=[],particles=[],rain=[];for(let i=0;i<130;i++)rain.push({x:randSeed(i+8)*1600,y:randSeed(i+240)*900,s:80+randSeed(i+500)*260});
function buildingAt(index){const x=index*280+randSeed(index+17)*130-60,height=240+randSeed(index+401)*310,bw=125+randSeed(index+903)*110,style=Math.floor(randSeed(index+29)*5);return{x,w:bw,h:height,style,id:index,antenna:randSeed(index+333)>.55,sign:randSeed(index+104)>.78}}function getBuildings(minX,maxX){let a=[];for(let i=Math.floor((minX-320)/280),to=Math.ceil((maxX+320)/280);i<=to;i++)a.push(buildingAt(i));return a}
function nearestAnchor(){let best=null,bd=Infinity;for(const b of getBuildings(player.x-800,player.x+950))for(const p of [b.x+10,b.x+b.w*.5,b.x+b.w-10]){let dx=p-player.x,dy=b.h-player.y,d=Math.hypot(dx,dy);if(dy>28&&d<560&&d<bd){best={x:p,y:b.h,b};bd=d}}return best}function nearestTarget(){let best=null,d=Infinity;for(const e of enemies)if(e.hp>0){let a=Math.hypot(e.x-player.x,e.y-player.y);if(a<d){best=e;d=a}}return d<270?best:null}
function showToast(title,sub=''){let el=$('#toast');el.innerHTML=title+(sub?`<small>${sub}</small>`:'');el.classList.add('show');toastTimer=1.6}function addBurst(x,y,color,n=12){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=45+Math.random()*190;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.45+Math.random()*.55,color,size:1.5+Math.random()*3})}}
function startGame(){started=true;$('#start').classList.add('hidden');last=performance.now();showToast('SIGNAL ACQUIRED','Syndicate courier located · Pier 41');requestAnimationFrame(frame)}$('#startButton').addEventListener('click',startGame);
function keyDown(e){let k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();if(!keys[k]){keys[k]=true;if(k===' '){if(player.swing)releaseSwing();else jump()}if(k==='f')pointLaunch();if(k==='j')attack();if(k==='k'||k==='shift')dodge()}if(k==='e')heldSwing=true}function keyUp(e){let k=e.key.toLowerCase();keys[k]=false;if(k==='e'){heldSwing=false;if(player.swing)releaseSwing()}}addEventListener('keydown',keyDown);addEventListener('keyup',keyUp);addEventListener('blur',()=>{for(const k in keys)keys[k]=false;heldSwing=false});
function jump(){if(player.ground){player.vy=470;player.ground=false;player.y+=2;player.style=clamp(player.style+4,0,100);addBurst(player.x,0,'#83ecff',5)}else if(player.swing)releaseSwing()}
function releaseSwing(){if(!player.swing)return;let s=player.swing,dx=player.x-s.x,dy=player.y-s.y,len=Math.hypot(dx,dy)||1,tx=-dy/len,ty=dx/len;if(tx*player.vx<0){tx*=-1;ty*=-1}let speed=Math.hypot(player.vx,player.vy);player.vx+=tx*(speed*.52+120);player.vy+=ty*(speed*.52+80);player.swing=null;player.style=clamp(player.style+7,0,100);showToast('WEB RELEASE','Momentum boost')}
function pointLaunch(){const a=nearestAnchor();if(!a){showToast('NO VALID ANCHOR','Aim toward a rooftop');return}player.swing=null;let dx=a.x-player.x,dy=a.y-player.y,d=Math.hypot(dx,dy)||1;player.vx=dx/d*620+130;player.vy=dy/d*560+300;player.y=Math.max(player.y,a.y-80);player.launchFlash=.5;player.focus=clamp(player.focus-9,0,100);player.style=clamp(player.style+10,0,100);addBurst(player.x,player.y,'#7cf2ff',18);showToast('POINT LAUNCH','THWIP · Rooftop transfer')}
function attack(){if(player.attack>0)return;player.attack=.25;let t=nearestTarget();if(t){t.hp--;t.stun=.38;player.vx+=Math.sign(t.x-player.x)*180;player.vy+=100;player.combo=Math.min(9,player.combo+1);player.style=clamp(player.style+14,0,100);player.comboTimer=2;addBurst(t.x,t.y,'#ffd174',17);showToast(player.combo>3?'CLEAN COMBO':'WEB STRIKE',`×${player.combo} · SYNDICATE DOWN`);if(t.hp<=0){missionDist-=320;player.focus=clamp(player.focus+12,0,100)}}else player.style=clamp(player.style+2,0,100)}
function dodge(){if(player.dodge>0)return;player.dodge=.42;player.invuln=.5;player.vx+=Math.sign(player.vx||1)*210;player.vy=Math.max(player.vy,190);player.focus=clamp(player.focus-7,0,100);player.style=clamp(player.style+8,0,100);$('#sense').classList.remove('on');showToast('PERFECT DODGE','Time dilation · counter window');slow=.72;setTimeout(()=>slow=0,260);let t=nearestTarget();if(t){t.hp--;t.stun=.6;addBurst(t.x,t.y,'#ff677b',15);player.combo++;player.comboTimer=2}}
/*NEXT*/

